INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(850, 'business development', '/ˈbɪznɪs dɪˈvɛləpmənt/', 'noun', '{"zh-TW":["業務發展"],"en":["activities aimed at growing a company''s opportunities"]}', NULL, 'business development manager / business development strategy', '[{"en":"The business development team identified new markets.","zh-TW":"業務發展團隊發現了新市場。"},{"en":"Business development requires creativity and persistence.","zh-TW":"業務發展需要創造力和堅持不懈。"}]', NULL, NULL, 5, 850, NULL),
(851, 'business entity', '/ˈbɪznɪs ˈentɪti/', 'noun', '{"zh-TW":["商業實體；法人"],"en":["a legally recognized unit established to conduct business"]}', NULL, 'incorporate a business entity / business entity type', '[{"en":"A limited liability company is the most popular business entity type.","zh-TW":"有限責任公司是最受歡迎的商業實體類型。"},{"en":"Each business entity must file separate tax returns.","zh-TW":"每個商業實體必須單獨申報稅務。"}]', NULL, NULL, 5, 851, NULL),
(852, 'business ethics', '/ˈbɪznɪs ˈeθɪks/', 'noun', '{"zh-TW":["商業道德"],"en":["the principles and moral standards that guide business decisions and conduct"]}', NULL, 'promote business ethics / violate business ethics', '[{"en":"A strong culture of business ethics reduces legal and reputational risk.","zh-TW":"強烈的商業道德文化降低了法律和聲譽風險。"},{"en":"Business ethics training is mandatory for all new employees.","zh-TW":"商業道德培訓對所有新員工都是強制性的。"}]', '{"adjective":"ethical"}', NULL, 5, 852, NULL),
(853, 'business hours', '/ˈbɪznɪs ˈaʊərz/', 'noun', '{"zh-TW":["營業時間；辦公時間"],"en":["the hours during which a business is open"]}', NULL, 'during business hours / outside business hours', '[{"en":"Our offices are open during regular business hours.","zh-TW":"我們的辦公室在正常辦公時間開放。"},{"en":"Please contact us during business hours for assistance.","zh-TW":"請在辦公時間內與我們聯繫以獲取協助。"}]', NULL, NULL, 5, 853, NULL),
(854, 'business intelligence', '/ˈbɪznɪs ɪnˈtelɪdʒəns/', 'noun', '{"zh-TW":["商業智慧"],"en":["the use of data analysis tools to make informed business decisions"]}', NULL, 'business intelligence tools / business intelligence dashboard / leverage business intelligence', '[{"en":"Business intelligence data guided the expansion strategy.","zh-TW":"商業智慧數據指導了擴張策略。"},{"en":"The BI team built dashboards to monitor sales performance.","zh-TW":"商業智慧團隊建立了儀表板以監控銷售績效。"}]', '{"abbreviation":"BI"}', NULL, 5, 854, NULL),
(855, 'business interruption', '/ˈbɪznɪs ˌɪntəˈrʌpʃən/', 'noun', '{"zh-TW":["業務中斷"],"en":["a disruption to normal business operations causing financial loss"]}', NULL, 'business interruption insurance / business interruption claim', '[{"en":"The flood caused significant business interruption for the warehouse facility.","zh-TW":"洪水對倉庫設施造成了嚴重的業務中斷。"},{"en":"Business interruption insurance covers lost revenue during operational downtime.","zh-TW":"業務中斷保險涵蓋運營停機期間的收入損失。"}]', NULL, NULL, 5, 855, NULL),
(856, 'business lounge', '/''bɪznɪs laʊndʒ/', 'noun', '{"zh-TW":["商務休息室；貴賓室"],"en":["a premium area in an airport or hotel offering comfortable facilities for business travelers"]}', NULL, 'access the business lounge / business lounge membership / business lounge facilities', '[{"en":"Priority cardholders have complimentary access to the business lounge.","zh-TW":"優先卡持有人可以免費使用商務休息室。"},{"en":"The business lounge offered Wi-Fi, printing facilities, and hot meals.","zh-TW":"商務休息室提供Wi-Fi、列印設施和熱食。"}]', NULL, NULL, 5, 856, NULL),
(857, 'business model', '/ˈbɪznɪs ˈmɒdəl/', 'noun', '{"zh-TW":["商業模式"],"en":["the strategy a company uses to generate revenue and profit"]}', NULL, 'develop a business model / sustainable business model', '[{"en":"The company pivoted its business model to focus on subscriptions.","zh-TW":"公司將其商業模式轉向了訂閱服務。"},{"en":"A scalable business model supports rapid growth without proportional cost increases.","zh-TW":"可擴展的商業模式支持快速增長而不帶來同比例的成本增加。"}]', NULL, NULL, 5, 857, NULL),
(858, 'business plan', '/ˈbɪznɪs plæn/', 'noun', '{"zh-TW":["商業計劃；商業計劃書"],"en":["a written document outlining a business goals and strategies"]}', NULL, 'prepare a business plan / review the business plan', '[{"en":"Investors required a detailed business plan before committing funds.","zh-TW":"投資者在承諾資金前要求了詳細的商業計劃書。"},{"en":"The business plan projected profitability within 18 months.","zh-TW":"商業計劃預計在18個月內達到盈利。"}]', NULL, NULL, 5, 858, NULL),
(859, 'business process reengineering', '/ˈbɪznɪs ˈprɒses ˌriːˌendʒɪˈnɪərɪŋ/', 'noun', '{"zh-TW":["業務流程再造"],"en":["a radical redesign of business processes to achieve major improvements in performance"]}', NULL, 'implement business process reengineering / business process reengineering initiative', '[{"en":"Business process reengineering reduced order processing time from 10 days to 2.","zh-TW":"業務流程再造將訂單處理時間從10天縮短到了2天。"},{"en":"Successful business process reengineering requires strong leadership commitment.","zh-TW":"成功的業務流程再造需要強有力的領導層承諾。"}]', '{"abbreviation":"BPR"}', NULL, 5, 859, NULL),
(860, 'business trip', '/ˈbɪznɪs trɪp/', 'noun', '{"zh-TW":["商務出差；公務旅行"],"en":["a journey made for work purposes"]}', NULL, 'go on a business trip / business trip expenses', '[{"en":"He went on a business trip to Tokyo for three days.","zh-TW":"他出差去東京出差了三天。"},{"en":"All business trip expenses must be submitted with receipts.","zh-TW":"所有出差費用必須附有收據提交。"}]', NULL, NULL, 5, 860, NULL),
(861, 'busy', '/ˈbɪzi/', 'adjective', '{"zh-TW":["忙碌的"],"en":["having a lot to do"]}', NULL, 'busy schedule / busy season; busy with / busy schedule', '[{"en":"She has a very busy schedule this week.","zh-TW":"她這週行程非常忙碌。"},{"en":"December is our busiest season.","zh-TW":"十二月是我們最忙碌的季節。"},{"en":"I''m too busy to talk now.","zh-TW":"我現在太忙了，沒時間說話。"},{"en":"The restaurant is always busy.","zh-TW":"這家餐廳總是很忙。"}]', '{"adjective":"busy","adverb":"busily","noun":"business"}', NULL, 1, 861, NULL),
(862, 'butler', '/ˈbʌtlər/', 'noun', '{"zh-TW":["管家"],"en":["a personal attendant who looks after guests"]}', NULL, 'personal butler / butler service', '[{"en":"The presidential suite comes with a dedicated butler.","zh-TW":"總統套房配有專屬管家。"},{"en":"The butler arranged all the room service requests.","zh-TW":"管家安排了所有的客房服務要求。"}]', NULL, NULL, 2, 862, NULL),
(863, 'butler service', '/ˈbʌtlər ˈsɜːrvɪs/', 'noun', '{"zh-TW":["管家服務"],"en":["personalized assistance provided by a hotel butler"]}', NULL, 'request butler service / premium butler service', '[{"en":"The presidential suite comes with 24-hour butler service.","zh-TW":"總統套房提供24小時管家服務。"},{"en":"Butler service includes unpacking luggage and drawing baths.","zh-TW":"管家服務包括整理行李和放洗澡水。"}]', NULL, NULL, 5, 863, NULL),
(864, 'butter', '/ˈbʌtər/', 'noun', '{"zh-TW":["奶油"],"en":["a yellow food made from cream"]}', NULL, 'bread and butter / peanut butter', '[{"en":"Spread some butter on the toast.","zh-TW":"在吐司上抹些奶油。"},{"en":"I love peanut butter.","zh-TW":"我喜歡花生醬。"}]', NULL, NULL, 2, 864, NULL),
(865, 'button', '/ˈbʌtən/', 'noun', '{"zh-TW":["按鈕；鈕扣"],"en":["a small round object for fastening clothes"]}', NULL, 'push the button / belly button', '[{"en":"Press the button to start.","zh-TW":"按下按鈕開始。"},{"en":"A button fell off my shirt.","zh-TW":"我襯衫上掉了一顆鈕扣。"}]', NULL, NULL, 2, 865, NULL),
(866, 'buy', '/baɪ/', 'verb', '{"zh-TW":["購買","買"],"en":["to obtain something by paying money","to get something by paying money"]}', NULL, 'buy in bulk / buy online; buy into / best buy', '[{"en":"We buy office supplies in bulk.","zh-TW":"我們大量採購辦公用品。"},{"en":"More people buy products online now.","zh-TW":"現在更多人在網路上購物。"},{"en":"I want to buy a new phone.","zh-TW":"我想買一支新手機。"},{"en":"She bought groceries after work.","zh-TW":"她下班後買了雜貨。"}]', '{"verb":"buy","noun":"buyer","noun2":"purchase"}', NULL, 1, 866, NULL),
(867, 'buyback', '/ˈbaɪbæk/', 'noun', '{"zh-TW":["回購"],"en":["a company''s repurchase of its own shares from the market"]}', NULL, 'share buyback / stock buyback / announce a buyback program', '[{"en":"The company announced a 500 million dollar share buyback program.","zh-TW":"公司宣佈了5億美元的股票回購計劃。"},{"en":"Buybacks increase earnings per share by reducing shares outstanding.","zh-TW":"回購通過減少流通股數量提高了每股盈餘。"}]', '{"verb":"buy back"}', NULL, 3, 867, NULL),
(868, 'buyback program', '/ˈbaɪbæk ˈproʊɡræm/', 'noun', '{"zh-TW":["回購計劃"],"en":["a corporate program to repurchase its own outstanding shares"]}', NULL, 'launch a buyback program / approve a buyback program', '[{"en":"The board approved a 100 million dollar buyback program.","zh-TW":"董事會批准了1億美元的回購計劃。"},{"en":"A share buyback program signals management confidence in the stock.","zh-TW":"股份回購計劃表明管理層對股票的信心。"}]', NULL, NULL, 5, 868, NULL),
(869, 'buyer', '/ˈbaɪər/', 'noun', '{"zh-TW":["買方；採購商"],"en":["a person or organization that purchases goods or services"]}', NULL, 'negotiate with the buyer / attract buyers / corporate buyer', '[{"en":"The buyer insisted on a 30-day payment term.","zh-TW":"買方堅持要求30天付款期。"},{"en":"Corporate buyers require formal purchase orders before delivery.","zh-TW":"企業採購商在交貨前需要正式採購訂單。"}]', '{"verb":"buy","adjective":"buying"}', NULL, 2, 869, NULL),
(870, 'buyer persona', '/ˈbaɪər pərˈsoʊnə/', 'noun', '{"zh-TW":["買家人物誌；客戶畫像"],"en":["a fictional representation of an ideal customer based on research"]}', NULL, 'create a buyer persona / define buyer personas / buyer persona template', '[{"en":"Understanding your buyer persona improves targeting accuracy.","zh-TW":"了解買家人物誌提高了目標定位的準確性。"},{"en":"The marketing team developed three distinct buyer personas.","zh-TW":"行銷團隊開發了三個不同的買家人物誌。"}]', '{"plural":"buyer personas"}', NULL, 5, 870, NULL),
(871, 'buyer''s market', '/ˈbaɪərz ˈmɑːrkɪt/', 'noun', '{"zh-TW":["買方市場"],"en":["a market condition where supply exceeds demand, giving buyers more negotiating power"]}', NULL, 'operate in a buyer''s market / buyer''s market conditions', '[{"en":"In a buyer''s market, suppliers must offer better terms to win contracts.","zh-TW":"在買方市場中，供應商必須提供更好的條款來贏得合約。"},{"en":"Falling house prices signal a buyer''s market in real estate.","zh-TW":"房價下跌預示著房地產市場的買方市場。"}]', '{"opposite":"seller''s market"}', NULL, 5, 871, NULL),
(872, 'buyout', '/ˈbaɪaʊt/', 'noun', '{"zh-TW":["買斷；收購"],"en":["the purchase of a controlling interest in a company"]}', NULL, 'management buyout / leveraged buyout / buyout firm', '[{"en":"The management buyout gave executives full ownership.","zh-TW":"管理層收購讓高管獲得了全部所有權。"},{"en":"Private equity firms specialize in buyout transactions.","zh-TW":"私募股權公司專注於收購交易。"}]', '{"verb":"buy out"}', NULL, 2, 872, 754),
(873, 'bylaws', '/ˈbaɪlɔːz/', 'noun', '{"zh-TW":["章程；內部規則"],"en":["rules and regulations adopted by a corporation or organization"]}', NULL, 'amend the bylaws / adopt bylaws / comply with bylaws', '[{"en":"The company''s bylaws specify how directors are elected.","zh-TW":"公司章程規定了董事的選舉方式。"},{"en":"The board voted to amend the bylaws at the emergency meeting.","zh-TW":"董事會在緊急會議上投票修訂了章程。"}]', '{"singular":"bylaw"}', NULL, 2, 873, NULL),
(874, 'byproduct', '/ˈbaɪprɒdʌkt/', 'noun', '{"zh-TW":["副產品"],"en":["something produced in addition to the main product"]}', NULL, 'industrial byproduct / unexpected byproduct', '[{"en":"Innovation was a byproduct of the research.","zh-TW":"創新是研究的副產品。"},{"en":"We recycle industrial byproducts.","zh-TW":"我們回收工業副產品。"}]', '{"noun":"byproduct"}', NULL, 3, 874, NULL),
(875, 'byte', '/baɪt/', 'noun', '{"zh-TW":["位元組"],"en":["a unit of digital information equal to eight bits"]}', NULL, 'kilobyte / megabyte / one byte', '[{"en":"A gigabyte equals approximately one billion bytes.","zh-TW":"一千兆位元組約等於十億位元組。"},{"en":"The file size is only a few hundred bytes after compression.","zh-TW":"壓縮後文件大小只有幾百位元組。"}]', NULL, NULL, 1, 875, NULL),
(876, 'cabin crew', '/ˈkæbɪn kruː/', 'noun', '{"zh-TW":["空服員"],"en":["staff who look after passengers on a plane"]}', NULL, 'friendly cabin crew / experienced cabin crew', '[{"en":"The cabin crew demonstrated the safety procedures.","zh-TW":"空服員示範了安全程序。"},{"en":"Please follow the instructions from the cabin crew.","zh-TW":"請遵循空服員的指示。"}]', NULL, NULL, 4, 876, NULL),
(877, 'cabinet', '/ˈkæbɪnɪt/', 'noun', '{"zh-TW":["內閣；櫥櫃","櫥櫃；內閣"],"en":["the group of senior government ministers","a piece of furniture with shelves","a group of senior government ministers"]}', '{"root":{"text":"cabin","meaning":"small room (小房間)"},"suffix":{"text":"-et","meaning":"small (小)"},"logic":"小房間狀的儲物家具，或指內閣。"}', 'cabinet meeting / cabinet minister; kitchen cabinet / cabinet meeting / filing cabinet', '[{"en":"The cabinet met to discuss the crisis.","zh-TW":"內閣開會討論危機。"},{"en":"She was appointed to the cabinet.","zh-TW":"她被任命進入內閣。"},{"en":"The dishes are in the cabinet above the sink.","zh-TW":"碗盤在水槽上方的櫥櫃裡。"},{"en":"The cabinet approved the new policy.","zh-TW":"內閣批准了新政策。"}]', NULL, NULL, 3, 877, NULL),
(878, 'cache', '/kæʃ/', 'noun', '{"zh-TW":["快取"],"en":["stored data for quick access"]}', NULL, 'clear cache / cache memory', '[{"en":"Clear the cache to fix the issue.","zh-TW":"清除快取來解決問題。"},{"en":"The browser stores data in the cache.","zh-TW":"瀏覽器將資料存在快取中。"}]', NULL, NULL, 2, 878, NULL),
(879, 'caching strategy', '/ˈkæʃɪŋ ˈstrætədʒi/', 'noun', '{"zh-TW":["快取策略"],"en":["a plan for determining what to cache, how long to cache it, and when to invalidate it"]}', NULL, 'implement caching strategy / define caching strategy / optimize caching strategy', '[{"en":"The team adopted a caching strategy to reduce repeated database calls.","zh-TW":"團隊採用了快取策略來減少重複的資料庫調用。"},{"en":"An effective caching strategy can dramatically improve application performance.","zh-TW":"有效的快取策略可以顯著提高應用程式性能。"}]', NULL, NULL, 5, 879, NULL),
(880, 'cadence', '/ˈkeɪdəns/', 'noun', '{"zh-TW":["節奏；步調"],"en":["a regular recurring sequence or rhythm"]}', NULL, 'business cadence / meeting cadence / release cadence', '[{"en":"The team established a weekly cadence for status reporting.","zh-TW":"團隊為狀態報告建立了每週節奏。"},{"en":"The cadence of product releases accelerated under the new CTO.","zh-TW":"在新任CTO領導下，產品發布的節奏加快了。"}]', NULL, NULL, 3, 880, NULL),
(881, 'cafeteria', '/ˌkæfɪˈtɪəriə/', 'noun', '{"zh-TW":["自助餐廳；食堂"],"en":["a restaurant where customers serve themselves"]}', NULL, 'school cafeteria / office cafeteria', '[{"en":"The company cafeteria offers a variety of healthy meals.","zh-TW":"公司食堂提供各種健康餐食。"},{"en":"Students eat lunch in the school cafeteria.","zh-TW":"學生在學校食堂吃午餐。"}]', NULL, NULL, 3, 881, NULL),
(882, 'cage', '/keɪdʒ/', 'noun', '{"zh-TW":["籠子"],"en":["a structure of bars for keeping animals"]}', NULL, 'bird cage / cage match', '[{"en":"The bird escaped from its cage.","zh-TW":"鳥從籠子裡逃了出來。"},{"en":"The lion paced in its cage.","zh-TW":"獅子在籠子裡踱步。"}]', '{"verb":"cage","adjective":"caged"}', NULL, 1, 882, NULL),
(883, 'cake', '/keɪk/', 'noun', '{"zh-TW":["蛋糕"],"en":["a sweet baked food"]}', NULL, 'piece of cake / birthday cake', '[{"en":"Would you like some cake?","zh-TW":"你想要一些蛋糕嗎？"},{"en":"That test was a piece of cake.","zh-TW":"那個考試太容易了。"}]', NULL, NULL, 1, 883, NULL),
(884, 'calculate', '/ˈkælkjʊleɪt/', 'verb', '{"zh-TW":["計算；估算","計算"],"en":["to determine by mathematical process","to determine by mathematical methods"]}', '{"root":{"text":"calcul","meaning":"pebble/count (石子/計數)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"用石子計數，即「計算」。"}', 'calculate costs/risk/profit; calculate the cost / carefully calculated', '[{"en":"We need to calculate the total project cost.","zh-TW":"我們需要計算專案總成本。"},{"en":"The software calculates tax automatically.","zh-TW":"軟體會自動計算稅金。"},{"en":"Can you calculate the total cost?","zh-TW":"你能計算總費用嗎？"},{"en":"The risk was carefully calculated.","zh-TW":"風險經過仔細計算。"}]', '{"noun":"calculation","noun2":"calculator"}', NULL, 3, 884, NULL),
(885, 'calculation', 'ˌkælkjʊˈleɪʃən', 'noun', '{"zh-TW":["計算；估算","推算"],"en":["a mathematical process","a careful estimate"]}', NULL, 'rough calculation/final calculation', '[{"en":"Please double-check the calculation.","zh-TW":"請仔細核對計算結果。"}]', '{"verb":"calculate","adjective":"calculated","adverb":"calculatedly"}', NULL, 4, 885, 518),
(886, 'calibrate', '/''kælɪbreɪt/', 'verb', '{"zh-TW":["校準；校正"],"en":["to carefully assess, set, or adjust something to achieve a desired result; to mark with a scale"]}', NULL, 'calibrate expectations / calibrate the approach / calibrate equipment', '[{"en":"Leaders must calibrate their communication style to suit different audiences.","zh-TW":"領導者必須校準他們的溝通方式，以適應不同的受眾。"},{"en":"The technician calibrated the machines before the production run started.","zh-TW":"技術員在生產運行開始前校準了機器。"}]', '{"noun":"calibration"}', NULL, 3, 886, NULL),
(887, 'call', '/kɔːl/', 'verb', '{"zh-TW":["打電話；稱呼"],"en":["to telephone","to give a name to"]}', NULL, 'call back / conference call', '[{"en":"I will call you back in five minutes.","zh-TW":"我五分鐘後回電給你。"},{"en":"We have a conference call at 3 p.m.","zh-TW":"我們下午3點有一通電話會議。"}]', '{"verb":"call","noun":"call","noun2":"caller"}', NULL, 1, 887, NULL),
(888, 'call center', '/kɔːl ˈsentər/', 'noun', '{"zh-TW":["客服中心；呼叫中心"],"en":["a centralized office handling incoming and outgoing telephone calls"]}', NULL, 'manage a call center / call center agent', '[{"en":"The company outsourced its call center operations to reduce costs.","zh-TW":"公司外包了其客服中心業務以降低成本。"},{"en":"Response times at the call center improved after additional staffing.","zh-TW":"增加人員後，客服中心的響應時間有所改善。"}]', NULL, NULL, 4, 888, NULL),
(889, 'call option', '/kɔːl ˈɒpʃən/', 'noun', '{"zh-TW":["認購期權；買權"],"en":["the right to buy an asset at a specified price within a set period"]}', NULL, 'buy a call option / exercise a call option', '[{"en":"Investors bought call options to profit from an expected price rise.","zh-TW":"投資者購買了認購期權以從預期的價格上漲中獲利。"},{"en":"Call options are used to hedge against rising input costs.","zh-TW":"認購期權用於對沖上漲的投入成本。"}]', '{"opposite":"put option"}', NULL, 4, 889, NULL),
(890, 'call to action', '/kɔːl tə ˈækʃən/', 'noun', '{"zh-TW":["行動號召"],"en":["a prompt encouraging the audience to take an immediate action"]}', NULL, 'include a call to action / clear call to action / call to action button', '[{"en":"The email ended with a strong call to action to sign up for the webinar.","zh-TW":"電子郵件以強烈的行動號召結束，邀請讀者報名網路研討會。"},{"en":"Every landing page should have one primary call to action.","zh-TW":"每個登陸頁應有一個主要的行動號召。"}]', '{"abbreviation":"CTA"}', NULL, 5, 890, NULL),
(891, 'callable', '/ˈkɔːləbəl/', 'adjective', '{"zh-TW":["可贖回的；可召回的"],"en":["able to be redeemed or called by the issuer before maturity"]}', NULL, 'callable bond / callable loan', '[{"en":"Callable bonds give the issuer the option to repay early.","zh-TW":"可贖回債券賦予發行者提前還款的選擇權。"},{"en":"The callable feature reduces yield for investors.","zh-TW":"可贖回特徵降低了投資者的收益率。"}]', NULL, NULL, 3, 891, NULL),
(892, 'callable bond', '/ˈkɔːləbəl bɒnd/', 'noun', '{"zh-TW":["可贖回債券"],"en":["a bond that can be redeemed by the issuer before its maturity date"]}', NULL, 'issue a callable bond / callable bond provision', '[{"en":"The issuer redeemed the callable bond early when interest rates fell.","zh-TW":"當利率下降時，發行人提前贖回了可贖回債券。"},{"en":"Callable bonds typically offer higher yields to compensate for early redemption risk.","zh-TW":"可贖回債券通常提供較高的殖利率以補償提前贖回風險。"}]', NULL, NULL, 5, 892, NULL),
(893, 'callback', '/ˈkɔːlbæk/', 'noun', '{"zh-TW":["回電；回撥"],"en":["a phone call made in response to a missed call or request"]}', NULL, 'request a callback / schedule a callback', '[{"en":"Please leave your number and we will arrange a callback.","zh-TW":"請留下您的電話，我們將安排回電。"},{"en":"The customer requested a callback within the hour.","zh-TW":"顧客要求在一小時內回電。"}]', '{"verb":"call back"}', NULL, 3, 893, NULL),
(894, 'calm', '/kɑːm/', 'adjective', '{"zh-TW":["平靜的；冷靜的"],"en":["not excited or upset; peaceful","not showing or feeling nervousness or anger"]}', '{"root":{"text":"calm","meaning":"still/quiet (靜止)"},"logic":"源自希臘語 kauma（炎熱中的休息），指平靜狀態。"}', 'stay calm / calm down; stay calm / calm down / calm and collected', '[{"en":"Please stay calm during the evacuation.","zh-TW":"疏散時請保持冷靜。"},{"en":"The manager remained calm under pressure.","zh-TW":"經理在壓力下保持冷靜。"},{"en":"Please stay calm during the emergency.","zh-TW":"緊急情況時請保持冷靜。"},{"en":"The sea was perfectly calm that morning.","zh-TW":"那天早上海面非常平靜。"}]', '{"adjective":"calm","verb":"calm","noun":"calmness","adverb":"calmly"}', NULL, 1, 894, NULL),
(895, 'caloric intake', '/''kæˈlɒrɪk ˌɪnteɪk/', 'noun', '{"zh-TW":["卡路里攝取量；熱量攝取"],"en":["the total amount of calories consumed through food and drink in a given period"]}', NULL, 'monitor caloric intake / daily caloric intake / reduce caloric intake', '[{"en":"Reducing daily caloric intake by five hundred calories can lead to gradual weight loss.","zh-TW":"每日減少五百卡路里的攝取量可以帶來逐漸的體重減輕。"},{"en":"The nutritionist calculated the ideal caloric intake based on her activity level.","zh-TW":"營養師根據她的活動水平計算了理想的卡路里攝取量。"}]', NULL, NULL, 5, 895, NULL),
(896, 'calorie', '/''kæləri/', 'noun', '{"zh-TW":["卡路里；熱量單位"],"en":["a unit of energy, used in measuring the energy value of food"]}', NULL, 'count calories / calorie intake / high-calorie', '[{"en":"She tracked her daily calorie intake to maintain a healthy weight.","zh-TW":"她追蹤每日卡路里攝取量以維持健康體重。"},{"en":"A single tablespoon of olive oil contains about 120 calories.","zh-TW":"一湯匙橄欖油含約120卡路里。"}]', '{"adjective":"caloric"}', NULL, 3, 896, NULL),
(897, 'calorie counting', '/''kæləri ˌkaʊntɪŋ/', 'noun', '{"zh-TW":["計算卡路里；熱量計算"],"en":["the practice of tracking caloric intake as a method of managing weight"]}', NULL, 'try calorie counting / calorie counting app / benefit of calorie counting', '[{"en":"She used a calorie counting app to monitor her daily food intake.","zh-TW":"她使用卡路里計算應用程式監控每日食物攝取量。"},{"en":"Calorie counting helped her understand which foods were causing weight gain.","zh-TW":"計算卡路里幫助她了解哪些食物導致體重增加。"}]', NULL, NULL, 5, 897, NULL),
(898, 'calorie deficit', '/''kæləri ˌdefɪsɪt/', 'noun', '{"zh-TW":["熱量赤字；卡路里缺口"],"en":["the state in which the body burns more calories than it consumes, leading to weight loss"]}', NULL, 'create a calorie deficit / maintain a calorie deficit / calorie deficit diet', '[{"en":"A moderate calorie deficit of 500 calories per day is the recommended approach to weight loss.","zh-TW":"每天500卡路里的適度熱量赤字是推薦的減重方法。"},{"en":"She combined exercise and a calorie deficit to achieve her fitness goals.","zh-TW":"她結合運動和熱量赤字來實現健身目標。"}]', NULL, NULL, 5, 898, NULL),
(899, 'calorie-dense', '/''kæləri dens/', 'adjective', '{"zh-TW":["高熱量密度的；高卡路里的"],"en":["containing a large amount of calories relative to portion size"]}', NULL, 'calorie-dense food / calorie-dense snack / avoid calorie-dense', '[{"en":"Nuts and cheese are calorie-dense but also nutrient-rich foods.","zh-TW":"堅果和起司是高熱量密度的食物，但也富含營養素。"},{"en":"Calorie-dense foods should be eaten in moderation as part of a balanced diet.","zh-TW":"高熱量密度的食物應適量食用，作為均衡飲食的一部分。"}]', NULL, NULL, 5, 899, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(900, 'camera', '/ˈkæmərə/', 'noun', '{"zh-TW":["相機"],"en":["a device for taking photographs"]}', NULL, 'security camera / camera angle', '[{"en":"I forgot my camera at home.","zh-TW":"我把相機忘在家裡了。"},{"en":"The store has security cameras.","zh-TW":"商店裝有監視器。"}]', NULL, NULL, 2, 900, NULL),
(901, 'camp', '/kæmp/', 'noun', '{"zh-TW":["營地；露營"],"en":["a place with tents for staying outdoors"]}', NULL, 'summer camp / camp out', '[{"en":"The kids went to summer camp.","zh-TW":"孩子們去了夏令營。"},{"en":"We camped by the lake.","zh-TW":"我們在湖邊露營。"}]', '{"verb":"camp","noun2":"camping","noun3":"campsite"}', NULL, 1, 901, NULL),
(902, 'campaign', '/kæmˈpeɪn/', 'noun', '{"zh-TW":["活動；運動","宣傳","競選活動；運動","活動；競選"],"en":["an organized course of action to achieve a goal","organized activities to achieve a goal"]}', '{"root":{"text":"camp","meaning":"field (原野)"},"suffix":{"text":"-aign","meaning":"action (行動)"},"logic":"在原野上的行動，即「活動」。"}', 'marketing campaign / advertising campaign / launch a campaign; election campaign / advertising campaign; advertising campaign / election campaign / launch a campaign', '[{"en":"The marketing campaign generated significant leads.","zh-TW":"行銷活動產生了大量潛在客戶。"},{"en":"They launched a campaign to promote sustainability.","zh-TW":"他們發起了促進永續發展的活動。"},{"en":"The campaign starts next month.","zh-TW":"競選活動下個月開始。"},{"en":"They launched a campaign against smoking.","zh-TW":"他們發起了反菸運動。"},{"en":"The company launched a new marketing campaign.","zh-TW":"公司發起了新的行銷活動。"},{"en":"She is running a campaign for mayor.","zh-TW":"她正在競選市長。"}]', '{"verb":"campaign","noun2":"campaigner"}', NULL, 3, 902, NULL),
(903, 'campsite', '/''kæmpsaɪt/', 'noun', '{"zh-TW":["露營地；紮營地"],"en":["a place used for camping, especially one equipped with facilities"]}', NULL, 'book a campsite / campsite facilities / tent campsite', '[{"en":"We reserved a campsite near the river for the long weekend.","zh-TW":"我們為長週末預訂了河邊的露營地。"},{"en":"The campsite had clean restrooms, fire pits, and picnic tables.","zh-TW":"露營地有乾淨的洗手間、火坑和野餐桌。"}]', NULL, NULL, 3, 903, NULL),
(904, 'campus', '/ˈkæmpəs/', 'noun', '{"zh-TW":["校園"],"en":["the grounds of a university or college"]}', NULL, 'on campus / campus life', '[{"en":"The university has a beautiful campus.","zh-TW":"這所大學有一個美麗的校園。"},{"en":"Students live on campus.","zh-TW":"學生住在校園裡。"}]', NULL, NULL, 2, 904, NULL),
(905, 'campus life', '/''kæmpəs laɪf/', 'noun', '{"zh-TW":["校園生活"],"en":["the social and academic activities that take place at a college or university"]}', NULL, 'enjoy campus life / campus life experience / vibrant campus life', '[{"en":"She treasured her campus life experiences, including clubs, sports, and friendships.","zh-TW":"她珍視她的校園生活經歷，包括社團、運動和友誼。"},{"en":"Campus life offers many opportunities to develop skills beyond the classroom.","zh-TW":"校園生活提供了許多在課堂之外培養技能的機會。"}]', NULL, NULL, 4, 905, NULL),
(906, 'cancel', 'ˈkænsəl', 'verb', '{"zh-TW":["取消；撤銷","刪除"],"en":["to stop a planned event","to end an agreement"]}', NULL, 'cancel a meeting/cancel an order', '[{"en":"The meeting was cancelled due to the storm.","zh-TW":"由於暴風雨，會議被取消了。"}]', '{"noun":"cancellation","adjective":"cancelled"}', NULL, 2, 906, 14),
(907, 'cancellation', '/ˌkænsəˈleɪʃən/', 'noun', '{"zh-TW":["取消"],"en":["the action of cancelling a scheduled event"]}', NULL, 'flight cancellation / hotel cancellation', '[{"en":"The cancellation of the flight caused major delays.","zh-TW":"班機取消導致嚴重延誤。"},{"en":"We received a cancellation notice this morning.","zh-TW":"我們今天早上收到了取消通知。"}]', '{"verb":"cancel","adjective":"cancelled"}', NULL, 4, 907, NULL),
(908, 'cancellation fee', '/ˌkænsəˈleɪʃən fiː/', 'noun', '{"zh-TW":["取消費；違約金"],"en":["a charge levied when a booking or contract is cancelled"]}', NULL, 'charge a cancellation fee / waive the cancellation fee', '[{"en":"The hotel charged a one-night cancellation fee for late cancellations.","zh-TW":"酒店對逾期取消收取一晚的取消費。"},{"en":"The supplier agreed to waive the cancellation fee as a goodwill gesture.","zh-TW":"供應商同意作為善意表示豁免取消費。"}]', NULL, NULL, 5, 908, NULL),
(909, 'cancellation policy', '/ˌkænsəˈleɪʃən ˈpɒlɪsi/', 'noun', '{"zh-TW":["取消政策"],"en":["the rules governing cancellation of reservations"]}', NULL, 'strict cancellation policy / flexible cancellation policy', '[{"en":"Please read the cancellation policy before booking.","zh-TW":"預訂前請閱讀取消政策。"},{"en":"The hotel has a 48-hour cancellation policy.","zh-TW":"飯店有48小時取消政策。"}]', NULL, NULL, 5, 909, NULL),
(910, 'candid', '/''kændɪd/', 'adjective', '{"zh-TW":["坦誠的；直言不諱的"],"en":["truthful and straightforward; frank"]}', NULL, 'candid feedback / candid discussion / be candid', '[{"en":"She appreciated the manager''s candid feedback because it was honest and constructive.","zh-TW":"她很感激管理者坦誠的反饋，因為它是誠實且有建設性的。"},{"en":"The CEO was candid with investors about the challenges the company was facing.","zh-TW":"首席執行官對投資者坦誠地說明了公司面臨的挑戰。"}]', '{"adverb":"candidly","noun":"candor"}', NULL, 2, 910, NULL),
(911, 'candidate', '/ˈkændɪdət/', 'noun', '{"zh-TW":["候選人；應徵者"],"en":["a person who applies for a job or is nominated for a position"]}', '{"root":{"text":"candid","meaning":"white (白色)"},"suffix":{"text":"-ate","meaning":"person (人)"},"logic":"穿白袍的人（古羅馬參選者），即「候選人」。"}', 'ideal candidate / qualified candidate / shortlist candidates', '[{"en":"We interviewed five candidates for the position.","zh-TW":"我們面試了五位候選人。"},{"en":"The ideal candidate should have 5+ years of experience.","zh-TW":"理想候選人應有5年以上經驗。"}]', '{"noun":"candidacy"}', NULL, 3, 911, 15),
(912, 'canonical', '/kəˈnɒnɪkəl/', 'adjective', '{"zh-TW":["標準的；經典的；正統的"],"en":["conforming to an established standard; recognized as authoritative"]}', NULL, 'canonical text / canonical form / canonical example', '[{"en":"This paper is the canonical reference for the methodology.","zh-TW":"這篇論文是該方法論的標準參考文獻。"},{"en":"The canonical example of supply and demand is found in every economics textbook.","zh-TW":"供求的標準例子在每本經濟學教科書中都能找到。"}]', '{"adverb":"canonically","noun":"canon"}', NULL, 3, 912, NULL),
(913, 'canvas', '/ˈkænvəs/', 'noun', '{"zh-TW":["畫布"],"en":["a strong cloth used for painting on"]}', '{"root":{"text":"canvas","meaning":"hemp cloth (麻布)"},"logic":"源自拉丁語 cannabis（大麻），原指麻布。"}', 'oil on canvas / blank canvas', '[{"en":"The artist stretched a new canvas.","zh-TW":"藝術家繃上一塊新畫布。"},{"en":"The painting is oil on canvas.","zh-TW":"這幅畫是油畫。"}]', NULL, NULL, 2, 913, NULL),
(914, 'canvass', '/ˈkænvəs/', 'verb', '{"zh-TW":["進行調查；游說拉票"],"en":["to solicit votes or opinions; to investigate thoroughly"]}', NULL, 'canvass voters / canvass opinions / canvass an area', '[{"en":"Volunteers canvassed neighborhoods to encourage residents to vote.","zh-TW":"志願者在各社區游說，鼓勵居民投票。"},{"en":"The research team canvassed one thousand respondents about their spending habits.","zh-TW":"研究團隊對一千名受訪者進行了消費習慣調查。"}]', '{"noun":"canvasser"}', NULL, 3, 914, NULL),
(915, 'canyon', '/''kænjən/', 'noun', '{"zh-TW":["峽谷"],"en":["a deep gorge, typically one with a river flowing through it"]}', NULL, 'grand canyon / carved canyon / explore a canyon', '[{"en":"The canyon walls displayed millions of years of geological history.","zh-TW":"峽谷壁展示了數百萬年的地質歷史。"},{"en":"Rafting through the canyon was one of the most thrilling experiences of the trip.","zh-TW":"在峽谷中漂流是這次旅途中最令人興奮的體驗之一。"}]', NULL, NULL, 2, 915, NULL),
(916, 'cap', '/kæp/', 'noun', '{"zh-TW":["帽子；蓋子"],"en":["a type of soft hat; a covering for a bottle"]}', NULL, 'baseball cap / cap off', '[{"en":"He always wears a baseball cap.","zh-TW":"他總是戴著棒球帽。"},{"en":"Put the cap back on the bottle.","zh-TW":"把瓶蓋蓋回去。"}]', NULL, NULL, 1, 916, NULL),
(917, 'cap table', '/kæp ˈteɪbl/', 'noun', '{"zh-TW":["資本表；股權結構表"],"en":["a spreadsheet showing the equity ownership of a company"]}', NULL, 'maintain a cap table / cap table management / clean cap table', '[{"en":"The cap table was updated after each funding round.","zh-TW":"資本表在每輪融資後進行更新。"},{"en":"A messy cap table can complicate future fundraising.","zh-TW":"雜亂的資本表可能使未來融資複雜化。"}]', '{"full form":"capitalization table"}', NULL, 3, 917, NULL),
(918, 'capable', '/ˈkeɪpəbl/', 'adjective', '{"zh-TW":["有能力的"],"en":["having the ability or quality to do something","having the ability to do something"]}', '{"root":{"text":"cap","meaning":"take/hold (拿/容納)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"能夠容納的，即「有能力的」。"}', 'capable of / highly capable', '[{"en":"She is capable of managing large-scale projects.","zh-TW":"她有能力管理大型專案。"},{"en":"We need a capable leader for this division.","zh-TW":"我們需要一位有能力的人來領導這個部門。"},{"en":"She is capable of handling the task alone.","zh-TW":"她有能力獨自處理這項任務。"},{"en":"He is a highly capable manager.","zh-TW":"他是一位非常能幹的經理。"}]', '{"noun":"capability"}', NULL, 3, 918, 281),
(919, 'capacity', '/kəˈpæsəti/', 'noun', '{"zh-TW":["容量；能力","身份"],"en":["the maximum amount that can be contained","the ability or power to do something"]}', '{"root":{"text":"cap","meaning":"hold (容納)"},"suffix":{"text":"-acity","meaning":"state of (狀態)"},"logic":"能容納的狀態，即「容量」。"}', 'full capacity / production capacity / in the capacity of', '[{"en":"The factory is operating at full capacity.","zh-TW":"工廠正以滿產能運作。"},{"en":"He served in the capacity of financial advisor.","zh-TW":"他以財務顧問的身份服務。"}]', NULL, NULL, 3, 919, 78),
(920, 'capacity building', '/''kəˈpæsɪti ˌbɪldɪŋ/', 'noun', '{"zh-TW":["能力建設；能力培育"],"en":["the process of developing and strengthening the skills and resources needed to succeed"]}', NULL, 'focus on capacity building / capacity building program / invest in capacity building', '[{"en":"The NGO launched a capacity building program for local community leaders.","zh-TW":"這個非政府組織為當地社區領袖推出了能力建設計劃。"},{"en":"Capacity building initiatives help developing economies grow their skilled workforce.","zh-TW":"能力建設倡議幫助發展中經濟體培育熟練勞動力。"}]', NULL, NULL, 5, 920, NULL),
(921, 'capacity constraint', '/kəˈpæsɪti kənˈstreɪnt/', 'noun', '{"zh-TW":["產能限制；產能瓶頸"],"en":["a limitation on how much a system can produce or process"]}', NULL, 'face a capacity constraint / overcome a capacity constraint', '[{"en":"The factory faces a capacity constraint during peak seasons.","zh-TW":"工廠在旺季面臨產能限制。"},{"en":"Capacity constraints were addressed by outsourcing peak demand to a third party.","zh-TW":"產能限制通過將高峰需求外包給第三方得到了解決。"}]', NULL, NULL, 5, 921, NULL),
(922, 'capacity planning', '/kəˈpæsɪti ˈplænɪŋ/', 'noun', '{"zh-TW":["產能規劃；容量規劃"],"en":["determining the resources needed to meet future demand"]}', NULL, 'capacity planning process / capacity planning model / short-term capacity planning', '[{"en":"Capacity planning prevented bottlenecks during the holiday rush.","zh-TW":"產能規劃防止了假日高峰期間的瓶頸。"},{"en":"IT capacity planning ensures servers can handle peak traffic.","zh-TW":"IT容量規劃確保伺服器能夠處理峰值流量。"}]', '{"verb":"plan capacity"}', NULL, 5, 922, NULL),
(923, 'capacity utilization', '/kəˈpæsɪti ˌjuːtɪlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["產能利用率"],"en":["the percentage of potential output actually being achieved"]}', NULL, 'improve capacity utilization / capacity utilization rate', '[{"en":"Higher capacity utilization leads to lower per-unit costs.","zh-TW":"更高的產能利用率可降低單位成本。"},{"en":"The factory operated at 90% capacity utilization during peak season.","zh-TW":"工廠在旺季以90%的產能利用率運作。"}]', NULL, NULL, 5, 923, NULL),
(924, 'capex', '/ˈkeɪpeks/', 'noun', '{"zh-TW":["資本支出（縮寫）"],"en":["short for capital expenditure; funds used to acquire long-term assets"]}', NULL, 'reduce capex / capex budget / heavy capex', '[{"en":"The company cut capex to preserve cash during the downturn.","zh-TW":"公司在低迷期間削減資本支出以保存現金。"},{"en":"High capex requirements make the industry a barrier to new entrants.","zh-TW":"高資本支出要求使該行業對新進入者形成壁壘。"}]', NULL, NULL, 2, 924, NULL),
(925, 'capital', '/ˈkæpɪtl/', 'noun', '{"zh-TW":["【主要意義-名詞】首都；資本金","【次要意義-形容詞】大寫的（字母）","【次要意義-形容詞】死刑的（capital punishment = 死刑）","【次要意義-名詞】資本；資金"],"en":["[primary - noun] the most important city in a country; funds for investment","[secondary - adjective] relating to uppercase letters","[secondary - adjective] involving the death penalty","[secondary - noun] wealth used to generate income"]}', '{"root":{"text":"capit","meaning":"head (頭)"},"suffix":{"text":"-al","meaning":"relating to (有關的)"},"logic":"頭部（最重要的），即「首都、資本」。"}', 'capital punishment / capital gain / capital letter / venture capital / capital expenditure', '[{"en":"The company raised additional capital through a public stock offering.","zh-TW":"公司通過公開股票發行籌集了額外資本。"},{"en":"Capital expenditure on new equipment increased by 20 percent this year.","zh-TW":"今年新設備的資本支出增加了20%。"},{"en":"All company names must be written with a capital letter.","zh-TW":"所有公司名稱必須以大寫字母書寫。"}]', '{"verb":"capitalize","adjective":"capitalist"}', 'capital 的次要意義包括「大寫的」（capital letter）、「死刑的」（capital punishment）和「資本的」（capital gain/expenditure），TOEIC 財務文章中 capital expenditure 和 capital gain 是必考搭配。', 3, 925, 520),
(926, 'capital adequacy', '/ˈkæpɪtəl ˈædɪkwəsi/', 'noun', '{"zh-TW":["資本充足性；資本充足率"],"en":["the level of capital a financial institution must hold to cover risks"]}', NULL, 'maintain capital adequacy / capital adequacy ratio', '[{"en":"The bank maintained capital adequacy above regulatory minimums.","zh-TW":"銀行維持了高於監管最低標準的資本充足率。"},{"en":"Capital adequacy rules were tightened after the 2008 financial crisis.","zh-TW":"2008年金融危機後資本充足率規則收緊了。"}]', NULL, NULL, 5, 926, NULL),
(927, 'capital allocation', '/ˈkæpɪtəl ˌæləˈkeɪʃən/', 'noun', '{"zh-TW":["資本配置"],"en":["the process of distributing financial resources among different uses"]}', NULL, 'efficient capital allocation / capital allocation decision / optimize capital allocation', '[{"en":"Effective capital allocation is a core responsibility of corporate leaders.","zh-TW":"有效的資本配置是企業領導者的核心責任。"},{"en":"Poor capital allocation leads to wasted resources and suboptimal returns.","zh-TW":"不良的資本配置導致資源浪費和次優回報。"}]', NULL, NULL, 5, 927, NULL),
(928, 'capital budget', '/ˈkæpɪtəl ˈbʌdʒɪt/', 'noun', '{"zh-TW":["資本預算"],"en":["a plan for major long-term investments in assets or infrastructure"]}', NULL, 'approve the capital budget / capital budget request', '[{"en":"The capital budget allocated $5 million for plant and equipment upgrades.","zh-TW":"資本預算為廠房和設備升級分配了500萬元。"},{"en":"Capital budget decisions require executive approval above a set threshold.","zh-TW":"資本預算決策在超過設定門檻值時需要高管批准。"}]', NULL, NULL, 5, 928, NULL),
(929, 'capital efficiency', '/ˈkæpɪtəl ɪˈfɪʃənsi/', 'noun', '{"zh-TW":["資本效率"],"en":["the amount of value generated per unit of invested capital"]}', NULL, 'improve capital efficiency / capital efficiency ratio / optimize capital efficiency', '[{"en":"The board challenged management to improve capital efficiency.","zh-TW":"董事會要求管理層提升資本效率。"},{"en":"Companies with high capital efficiency generate more value per dollar invested.","zh-TW":"資本效率高的公司每投入一美元能產生更多價值。"}]', NULL, NULL, 5, 929, NULL),
(930, 'capital expenditure', '/ˈkæpɪtl ɪkˈspendɪtʃər/', 'noun', '{"zh-TW":["資本支出"],"en":["funds used to acquire or upgrade long-term assets"]}', NULL, 'capital expenditure budget / reduce capital expenditure', '[{"en":"Capital expenditure on new equipment totaled $10 million.","zh-TW":"新設備的資本支出共計1000萬美元。"},{"en":"The board approved a capital expenditure plan for expansion.","zh-TW":"董事會批准了用於擴張的資本支出計劃。"}]', '{"abbreviation":"capex","adjective":"capital"}', NULL, 5, 930, NULL),
(931, 'capital expenditure budget', '/ˈkæpɪtəl ɪkˈspendɪtʃər ˈbʌdʒɪt/', 'noun', '{"zh-TW":["資本支出預算"],"en":["funds allocated for acquiring or upgrading physical long-term assets"]}', NULL, 'approve capital expenditure budget / capital expenditure budget review', '[{"en":"The capital expenditure budget was cut by 30% due to the economic slowdown.","zh-TW":"由於經濟放緩，資本支出預算削減了30%。"},{"en":"A capital expenditure budget is reviewed and approved annually by the board.","zh-TW":"資本支出預算每年由董事會審查和批准。"}]', NULL, NULL, 5, 931, NULL),
(932, 'capital gain', '/ˈkæpɪtl ɡeɪn/', 'noun', '{"zh-TW":["資本利得；資本增益"],"en":["profit from selling an asset at a higher price than purchased"]}', NULL, 'capital gain tax / realize a capital gain / long-term capital gain', '[{"en":"He realized a capital gain after selling the property.","zh-TW":"他出售房產後獲得了資本利得。"},{"en":"Capital gains are taxed at a lower rate than ordinary income.","zh-TW":"資本利得的稅率低於普通收入。"}]', '{"plural":"capital gains"}', NULL, 4, 932, NULL),
(933, 'capital gains tax', '/ˈkæpɪtl ɡeɪnz tæks/', 'noun', '{"zh-TW":["資本利得稅"],"en":["tax on profit from the sale of assets that have increased in value"]}', NULL, 'pay capital gains tax / capital gains tax rate', '[{"en":"Capital gains tax is applied when shares are sold at a profit.","zh-TW":"股票以盈利出售時適用資本利得稅。"},{"en":"Some countries offer relief from capital gains tax for long-term holdings.","zh-TW":"一些國家為長期持有提供資本利得稅減免。"}]', NULL, NULL, 5, 933, NULL),
(934, 'capital injection', '/ˈkæpɪtl ɪnˈdʒekʃən/', 'noun', '{"zh-TW":["資本注入"],"en":["the addition of funds into a company by investors or shareholders"]}', NULL, 'require a capital injection / make a capital injection', '[{"en":"The government provided a capital injection to rescue the failing bank.","zh-TW":"政府向瀕臨倒閉的銀行提供了資本注入以救援。"},{"en":"A capital injection by private investors prevented bankruptcy.","zh-TW":"私人投資者的資本注入防止了破產。"}]', NULL, NULL, 5, 934, NULL),
(935, 'capital market', '/ˈkæpɪtəl ˈmɑːrkɪt/', 'noun', '{"zh-TW":["資本市場"],"en":["a financial market in which long-term debt or equity instruments are traded"]}', NULL, 'access the capital market / capital market development', '[{"en":"The company raised funds by issuing bonds in the capital market.","zh-TW":"公司通過在資本市場發行債券籌集資金。"},{"en":"Capital markets provide businesses with long-term financing.","zh-TW":"資本市場為企業提供長期融資。"}]', NULL, NULL, 5, 935, NULL),
(936, 'capital markets', '/ˈkæpɪtəl ˈmɑːrkɪts/', 'noun', '{"zh-TW":["資本市場"],"en":["financial markets where long-term debt and equity instruments are bought and sold"]}', NULL, 'access capital markets / deep capital markets / capital markets activity', '[{"en":"Well-developed capital markets allow companies to raise long-term financing efficiently.","zh-TW":"發達的資本市場使企業能夠有效地籌集長期融資。"},{"en":"The government issued bonds in domestic capital markets to fund infrastructure spending.","zh-TW":"政府在國內資本市場發行債券為基礎設施支出提供資金。"}]', NULL, NULL, 5, 936, NULL),
(937, 'capital raise', '/ˈkæpɪtəl reɪz/', 'noun', '{"zh-TW":["融資；資金募集"],"en":["the process of obtaining new funds from investors for business purposes"]}', NULL, 'complete a capital raise / capital raise proceeds', '[{"en":"The company completed a capital raise of $25 million to fund acquisitions.","zh-TW":"公司完成了2500萬元的融資以資助收購。"},{"en":"A successful capital raise depends on strong investor relations and financials.","zh-TW":"成功的融資依賴於強健的投資者關係和財務狀況。"}]', NULL, NULL, 5, 937, NULL),
(938, 'capital structure', '/ˈkæpɪtl ˈstrʌktʃər/', 'noun', '{"zh-TW":["資本結構"],"en":["the mix of debt and equity used to finance a company''s operations"]}', NULL, 'optimize capital structure / leverage capital structure / capital structure decisions', '[{"en":"The acquisition changed the company''s capital structure significantly.","zh-TW":"收購顯著改變了公司的資本結構。"},{"en":"A balanced capital structure minimizes the cost of capital.","zh-TW":"平衡的資本結構最小化了資本成本。"}]', NULL, NULL, 5, 938, NULL),
(939, 'capitalise', '/ˈkæpɪtəlaɪz/', 'verb', '{"zh-TW":["資本化；將…記入資本項目"],"en":["to record expenditure as an asset rather than expense; to fund adequately"]}', NULL, 'capitalise costs / capitalise an asset / well capitalised', '[{"en":"The firm decided to capitalise the development costs of the new software.","zh-TW":"公司決定將新軟體的開發成本資本化。"},{"en":"A well-capitalised bank can absorb unexpected losses.","zh-TW":"資本充足的銀行能夠吸收意外損失。"}]', '{"noun":"capitalisation","adjective":"capitalised"}', NULL, 4, 939, NULL),
(940, 'capitalization', '/ˌkæpɪtəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["資本化；市值"],"en":["the total value of a company''s outstanding shares; also the process of recording an expense as an asset"]}', NULL, 'market capitalization / large cap / small cap', '[{"en":"The company''s market capitalization exceeded one billion dollars.","zh-TW":"公司市值超過了十億美元。"},{"en":"Software development costs were capitalized rather than expensed.","zh-TW":"軟體開發成本被資本化而非費用化處理。"}]', '{"verb":"capitalize","adjective":"capitalized"}', NULL, 5, 940, 756),
(941, 'capitalization rate', '/ˌkæpɪtəlaɪˈzeɪʃən reɪt/', 'noun', '{"zh-TW":["資本化率"],"en":["the rate of return on a real estate investment property based on expected income"]}', NULL, 'apply a capitalization rate / determine the capitalization rate', '[{"en":"A lower capitalization rate suggests higher property value and lower risk.","zh-TW":"較低的資本化率表明物業價值較高且風險較低。"},{"en":"Investors use the capitalization rate to compare real estate returns.","zh-TW":"投資者使用資本化率比較房地產回報。"}]', '{"abbreviation":"cap rate"}', NULL, 5, 941, NULL),
(942, 'capitalize', '/ˈkæpɪtəlaɪz/', 'verb', '{"zh-TW":["利用；資本化"],"en":["to take advantage of an opportunity","to provide with capital"]}', '{"root":{"text":"capital","meaning":"capital (資本)"},"suffix":{"text":"-ize","meaning":"to make (使)"},"logic":"使成為資本（利用資源），即「利用」。"}', 'capitalize on opportunity / capitalize assets', '[{"en":"We must capitalize on this market opportunity.","zh-TW":"我們必須利用這個市場機會。"},{"en":"The startup needs to capitalize its operations.","zh-TW":"這家新創公司需要為營運提供資金。"}]', '{"noun":"capitalization"}', NULL, 4, 942, 651),
(943, 'capstone project', '/''kæpstəʊn ˌprɒdʒekt/', 'noun', '{"zh-TW":["頂石計畫；畢業專題"],"en":["a culminating academic project that demonstrates mastery of learning objectives"]}', NULL, 'complete a capstone project / capstone project presentation / final capstone project', '[{"en":"Her capstone project involved designing a sustainable housing solution for urban areas.","zh-TW":"她的畢業專題涉及為城市地區設計可持續住宅解決方案。"},{"en":"The capstone project required students to apply skills from all four years of study.","zh-TW":"畢業專題要求學生應用四年學習中的所有技能。"}]', NULL, NULL, 5, 943, NULL),
(944, 'captain', '/ˈkæptɪn/', 'noun', '{"zh-TW":["隊長；船長"],"en":["the leader of a team or ship"]}', NULL, 'team captain / captain of industry', '[{"en":"She is the team captain.","zh-TW":"她是隊長。"},{"en":"The captain steered the ship safely.","zh-TW":"船長安全地駕駛了船。"}]', NULL, NULL, 3, 944, NULL),
(945, 'capture', '/ˈkæptʃər/', 'verb', '{"zh-TW":["捕獲；佔領","吸引","捕獲；捕捉"],"en":["to take control or possession of","to attract and hold attention","to catch a person or animal"]}', '{"root":{"text":"capt","meaning":"take/seize (抓取)"},"suffix":{"text":"-ure","meaning":"action (動作)"},"logic":"抓取的動作，即「捕獲」。"}', 'capture market share / capture attention / capture data; capture attention / capture the moment', '[{"en":"The company captured 30% of the market share.","zh-TW":"公司佔據了30%的市場份額。"},{"en":"The presentation captured everyone''s attention.","zh-TW":"簡報吸引了所有人的注意力。"},{"en":"The photo captured the moment perfectly.","zh-TW":"這張照片完美地捕捉了那一刻。"},{"en":"The criminal was captured by police.","zh-TW":"罪犯被警察逮捕了。"}]', '{"noun":"capture"}', NULL, 3, 945, NULL),
(946, 'car', '/kɑːr/', 'noun', '{"zh-TW":["汽車"],"en":["a motor vehicle for passengers","a road vehicle with an engine"]}', NULL, 'by car / car park', '[{"en":"She drives to work by car.","zh-TW":"她開車上班。"},{"en":"The car park is behind the building.","zh-TW":"停車場在大樓後面。"},{"en":"I need to fix my car.","zh-TW":"我需要修理我的車。"}]', '{"noun":"car"}', NULL, 1, 946, NULL),
(947, 'car rental', '/kɑːr ˈrɛntəl/', 'noun', '{"zh-TW":["租車"],"en":["the service of renting a car for a period of time"]}', NULL, 'car rental company / car rental agreement', '[{"en":"We arranged a car rental at the destination airport.","zh-TW":"我們在目的地機場安排了租車。"},{"en":"The car rental fee includes insurance.","zh-TW":"租車費用包含保險。"}]', '{"verb":"rent","adjective":"rental"}', NULL, 4, 947, NULL),
(948, 'caramelized', '/''kærəməlaɪzd/', 'adjective', '{"zh-TW":["焦糖化的；使焦糖化的"],"en":["cooked or heated until the natural sugars turn brown and develop a rich flavor"]}', NULL, 'caramelized onions / caramelized sugar / caramelized vegetables', '[{"en":"Caramelized onions add sweetness and depth to soups and stews.","zh-TW":"焦糖化的洋蔥為湯和燉菜增添了甜味和深度。"},{"en":"The chef topped the crème brûlée with a perfectly caramelized sugar crust.","zh-TW":"廚師在烤布蕾上蓋上了完美焦糖化的糖皮。"}]', '{"verb":"caramelize"}', NULL, 4, 948, NULL),
(949, 'carbohydrate', '/''kɑːrbəʊˌhaɪdreɪt/', 'noun', '{"zh-TW":["碳水化合物"],"en":["one of the main food groups, including sugars and starches, that provide energy"]}', NULL, 'complex carbohydrate / refined carbohydrate / low-carbohydrate', '[{"en":"Carbohydrates are the body''s primary source of quick energy.","zh-TW":"碳水化合物是身體主要的快速能量來源。"},{"en":"Whole grains provide complex carbohydrates that release energy more slowly.","zh-TW":"全穀類提供複合碳水化合物，能更緩慢地釋放能量。"}]', '{"adjective":"carbohydrate-rich"}', NULL, 4, 949, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(950, 'carbon', '/ˈkɑːrbən/', 'noun', '{"zh-TW":["碳"],"en":["a chemical element found in all living things"]}', '{"root":{"text":"carbon","meaning":"coal (�ite)"},"logic":"源自拉丁語 carbo（煤炭）。"}', 'carbon dioxide / carbon footprint / carbon emissions', '[{"en":"Trees absorb carbon dioxide from the atmosphere.","zh-TW":"樹木從大氣中吸收二氧化碳。"},{"en":"We should reduce our carbon footprint.","zh-TW":"我們應該減少碳足跡。"}]', NULL, NULL, 2, 950, NULL),
(951, 'carbon capture', '/ˈkɑːrbən ˈkæptʃər/', 'noun', '{"zh-TW":["碳捕獲；碳捕捉"],"en":["the process of trapping and storing carbon dioxide emissions"]}', NULL, 'carbon capture technology / invest in carbon capture', '[{"en":"Carbon capture technology removes CO2 from the atmosphere.","zh-TW":"碳捕獲技術從大氣中去除二氧化碳。"},{"en":"The factory installed a carbon capture system to reduce emissions.","zh-TW":"工廠安裝了碳捕獲系統以減少排放量。"}]', NULL, NULL, 5, 951, NULL),
(952, 'carbon credit', '/ˈkɑːrbən ˈkredɪt/', 'noun', '{"zh-TW":["碳信用；碳排放許可"],"en":["a permit that allows a company to emit a certain amount of carbon dioxide"]}', NULL, 'purchase carbon credits / trade carbon credits / carbon credit market', '[{"en":"The company offset its emissions by purchasing carbon credits.","zh-TW":"公司通過購買碳信用額度來抵消其排放量。"},{"en":"Critics argue that carbon credits allow companies to avoid genuine emission cuts.","zh-TW":"批評者認為碳信用允許公司避免真正的減排。"}]', NULL, NULL, 5, 952, NULL),
(953, 'carbon emission', '/ˈkɑːrbən ɪˈmɪʃən/', 'noun', '{"zh-TW":["碳排放"],"en":["the release of carbon dioxide into the atmosphere"]}', NULL, 'reduce carbon emissions / carbon emission target', '[{"en":"The government set a target to reduce carbon emissions by 50%.","zh-TW":"政府設定了將碳排放量減少50%的目標。"},{"en":"Transportation is a major source of carbon emissions.","zh-TW":"交通運輸是碳排放的主要來源。"}]', NULL, NULL, 5, 953, NULL),
(954, 'carbon footprint', '/ˈkɑːrbən ˈfʊtprɪnt/', 'noun', '{"zh-TW":["碳足跡"],"en":["the total carbon dioxide released by an individual or organization"]}', NULL, 'reduce carbon footprint / calculate carbon footprint', '[{"en":"Flying frequently increases your carbon footprint significantly.","zh-TW":"頻繁搭機會大幅增加您的碳足跡。"},{"en":"Companies are looking for ways to reduce their carbon footprint.","zh-TW":"企業正在尋找減少碳足跡的方法。"}]', NULL, NULL, 5, 954, NULL),
(955, 'carbon neutral', '/ˈkɑːrbən ˈnjuːtrəl/', 'adjective', '{"zh-TW":["碳中和的"],"en":["not increasing the net amount of carbon dioxide in the atmosphere"]}', NULL, 'carbon neutral operation / become carbon neutral', '[{"en":"The company pledged to become carbon neutral by 2030.","zh-TW":"公司承諾到2030年實現碳中和。"},{"en":"Carbon neutral products offset their emissions through reforestation.","zh-TW":"碳中和產品透過植樹造林來抵消排放量。"}]', NULL, NULL, 5, 955, NULL),
(956, 'carbon offset', '/ˈkɑːrbən ˈɒfsɛt/', 'noun', '{"zh-TW":["碳補償；碳抵消"],"en":["a reduction in emissions to compensate for emissions elsewhere"]}', NULL, 'purchase a carbon offset / carbon offset program', '[{"en":"Travelers can purchase carbon offsets for their flights.","zh-TW":"旅客可以為其航班購買碳補償。"},{"en":"The company invested in carbon offset projects in developing countries.","zh-TW":"公司在發展中國家投資了碳補償項目。"}]', NULL, NULL, 5, 956, NULL),
(957, 'carbon sequestration', '/ˈkɑːrbən ˌsekwɪˈstreɪʃən/', 'noun', '{"zh-TW":["碳封存；碳固定"],"en":["the process of capturing and storing atmospheric carbon dioxide"]}', NULL, 'carbon sequestration technology / forest carbon sequestration / geological carbon sequestration', '[{"en":"Forests provide natural carbon sequestration by absorbing CO₂.","zh-TW":"森林通過吸收CO₂提供天然碳封存。"},{"en":"Carbon sequestration is a key strategy for achieving net zero emissions.","zh-TW":"碳封存是實現淨零排放的關鍵策略。"}]', '{"verb":"sequester carbon"}', NULL, 5, 957, NULL),
(958, 'carbon trading', '/ˈkɑːrbən ˈtreɪdɪŋ/', 'noun', '{"zh-TW":["碳交易"],"en":["a market system that allows buying and selling of carbon credits"]}', NULL, 'participate in carbon trading / carbon trading scheme', '[{"en":"Carbon trading encourages companies to reduce emissions.","zh-TW":"碳交易鼓勵企業減少排放量。"},{"en":"The carbon trading market has grown significantly in recent years.","zh-TW":"近年來碳交易市場大幅成長。"}]', NULL, NULL, 5, 958, NULL),
(959, 'card', '/kɑːrd/', 'noun', '{"zh-TW":["卡片；紙牌"],"en":["a piece of stiff paper; a credit card"]}', NULL, 'credit card / playing cards', '[{"en":"Can I pay by card?","zh-TW":"我可以刷卡嗎？"},{"en":"She sent me a birthday card.","zh-TW":"她寄了一張生日卡給我。"}]', NULL, NULL, 1, 959, NULL),
(960, 'cardiology', '/ˌkɑːrdiˈɒlədʒi/', 'noun', '{"zh-TW":["心臟病學；心臟科"],"en":["the branch of medicine dealing with heart disorders"]}', NULL, 'cardiology department / consult a cardiologist', '[{"en":"She was referred to the cardiology department for tests.","zh-TW":"她被轉介到心臟科進行檢查。"},{"en":"Advances in cardiology have saved millions of lives.","zh-TW":"心臟病學的進步挽救了數百萬生命。"}]', '{"noun":"cardiologist","adjective":"cardiac"}', NULL, 4, 960, NULL),
(961, 'cardiovascular', '/ˌkɑːrdiəʊˈvæskjʊlər/', 'adjective', '{"zh-TW":["心血管的"],"en":["relating to the heart and blood vessels"]}', NULL, 'cardiovascular disease / cardiovascular health / cardiovascular exercise', '[{"en":"Regular cardiovascular exercise reduces the risk of heart disease.","zh-TW":"規律的心血管運動降低了心臟病的風險。"},{"en":"The patient underwent a comprehensive cardiovascular evaluation.","zh-TW":"患者接受了全面的心血管評估。"}]', NULL, NULL, 5, 961, NULL),
(962, 'cardiovascular fitness', '/''kɑːrdiəʊˌvæskjələr ˌfɪtnəs/', 'noun', '{"zh-TW":["心肺適能；心血管健身"],"en":["the ability of the heart and lungs to deliver oxygen to muscles during sustained physical activity"]}', NULL, 'improve cardiovascular fitness / measure cardiovascular fitness / cardiovascular fitness test', '[{"en":"Regular running is one of the best ways to improve cardiovascular fitness.","zh-TW":"定期跑步是提高心肺適能的最佳方式之一。"},{"en":"The coach assessed the team''s cardiovascular fitness at the start of each season.","zh-TW":"教練在每個賽季開始時評估球隊的心肺適能。"}]', '{"adjective":"cardiovascular"}', NULL, 5, 962, NULL),
(963, 'career', '/kəˈrɪər/', 'noun', '{"zh-TW":["職業；職涯"],"en":["an occupation undertaken for a significant period of one''s life"]}', '{"root":{"text":"carr","meaning":"road/vehicle (路/車)"},"suffix":{"text":"-eer","meaning":"person engaged in (從事…的人)"},"logic":"人生道路上從事的，即「職業」。"}', 'career development / career path / career change', '[{"en":"She made a career change from finance to tech.","zh-TW":"她從金融轉職到科技業。"},{"en":"The company offers excellent career development opportunities.","zh-TW":"公司提供優秀的職涯發展機會。"}]', NULL, NULL, 2, 963, NULL),
(964, 'career development', '/kəˈrɪər dɪˈvɛləpmənt/', 'noun', '{"zh-TW":["職涯發展"],"en":["activities that help someone advance professionally"]}', NULL, 'support career development / career development program', '[{"en":"The company invests in employee career development.","zh-TW":"公司投資於員工的職涯發展。"},{"en":"A good manager supports the career development of their team.","zh-TW":"優秀的管理者支持其團隊成員的職涯發展。"}]', NULL, NULL, 5, 964, NULL),
(965, 'careful', '/ˈkɛərfəl/', 'adjective', '{"zh-TW":["小心的；仔細的"],"en":["giving attention to avoid mistakes or danger","giving attention to avoid danger or mistakes"]}', NULL, 'be careful / careful planning; be careful / careful with', '[{"en":"Be careful with the fragile items.","zh-TW":"小心處理易碎物品。"},{"en":"Careful planning led to success.","zh-TW":"仔細的規劃帶來了成功。"},{"en":"Be careful crossing the road.","zh-TW":"過馬路要小心。"},{"en":"She''s very careful with money.","zh-TW":"她花錢很謹慎。"}]', '{"adjective":"careful","adverb":"carefully","noun":"care","adjective2":"careless"}', NULL, 3, 965, NULL),
(966, 'cargo', '/ˈkɑːrɡəʊ/', 'noun', '{"zh-TW":["貨物"],"en":["goods carried by a vehicle, ship, or aircraft"]}', '{"root":{"text":"carg","meaning":"load (裝載)"},"suffix":{"text":"-o","meaning":"noun ending (名詞字尾)"},"logic":"裝載的東西，即「貨物」。"}', 'cargo ship / air cargo / cargo container', '[{"en":"The cargo was damaged during transit.","zh-TW":"貨物在運輸過程中受損。"},{"en":"Air cargo rates have increased significantly.","zh-TW":"空運費率大幅上漲。"}]', NULL, NULL, 2, 966, 833),
(967, 'cargo insurance', '/ˈkɑːrɡəʊ ɪnˈʃʊərəns/', 'noun', '{"zh-TW":["貨物保險"],"en":["insurance covering goods during transit"]}', NULL, 'obtain cargo insurance / cargo insurance claim', '[{"en":"Cargo insurance protects against loss during shipping.","zh-TW":"貨物保險保護貨物在運輸過程中免受損失。"},{"en":"Always obtain cargo insurance for high-value shipments.","zh-TW":"高價值貨物務必購買貨物保險。"}]', NULL, NULL, 5, 967, NULL),
(968, 'cargo manifest', '/''kɑːrɡəʊ ˌmænɪfest/', 'noun', '{"zh-TW":["貨物清單；貨艙清單"],"en":["a detailed list of all cargo loaded onto a ship, aircraft, or vehicle"]}', NULL, 'prepare a cargo manifest / submit a cargo manifest / accurate cargo manifest', '[{"en":"The customs officer reviewed the cargo manifest before clearing the shipment.","zh-TW":"海關官員在放行貨物前審查了貨物清單。"},{"en":"An accurate cargo manifest prevents delays and issues at the port.","zh-TW":"準確的貨物清單可以防止港口的延誤和問題。"}]', NULL, NULL, 5, 968, NULL),
(969, 'cargo tracking', '/''kɑːrɡəʊ ˌtrækɪŋ/', 'noun', '{"zh-TW":["貨物追蹤"],"en":["the monitoring of shipments in real time as they move through the supply chain"]}', NULL, 'use cargo tracking / cargo tracking system / real-time cargo tracking', '[{"en":"Cargo tracking technology allows companies to monitor shipments in real time.","zh-TW":"貨物追蹤技術使公司能夠實時監控貨物運輸。"},{"en":"Customers can use the cargo tracking app to see exactly where their orders are.","zh-TW":"客戶可以使用貨物追蹤應用程序確切地查看訂單所在位置。"}]', '{"verb":"track","noun":"tracking"}', NULL, 5, 969, NULL),
(970, 'carousel ad', '/ˈkærəsɛl æd/', 'noun', '{"zh-TW":["輪播廣告"],"en":["a digital ad format showing multiple scrollable images or products"]}', NULL, 'create a carousel ad / carousel ad performance', '[{"en":"Carousel ads on social media generated a 20% higher click rate.","zh-TW":"社群媒體上的輪播廣告產生了高20%的點擊率。"},{"en":"The team created a carousel ad showcasing the five product variants.","zh-TW":"團隊創建了展示五款產品變體的輪播廣告。"}]', NULL, NULL, 4, 970, NULL),
(971, 'carriage paid', '/ˈkærɪdʒ peɪd/', 'phrase', '{"zh-TW":["運費已付"],"en":["a trade term indicating the seller pays freight to a named destination"]}', NULL, 'ship carriage paid / carriage paid to destination', '[{"en":"The goods were delivered carriage paid to the buyer''s warehouse.","zh-TW":"貨物以運費已付的方式交付到買方倉庫。"},{"en":"Carriage paid terms shift delivery risk at the first carrier handover.","zh-TW":"運費已付條款在第一個承運人移交時轉移交付風險。"}]', '{"abbreviation":"CPT"}', NULL, 5, 971, NULL),
(972, 'carried interest', '/ˈkærid ˈɪntrəst/', 'noun', '{"zh-TW":["附帶權益；業績報酬"],"en":["the share of profits paid to fund managers as performance compensation"]}', NULL, 'earn carried interest / carried interest tax / manage carried interest', '[{"en":"Private equity managers typically earn a twenty percent carried interest.","zh-TW":"私募股權管理者通常賺取百分之二十的業績報酬。"},{"en":"Carried interest aligns manager incentives with fund performance.","zh-TW":"附帶權益使管理者的激勵與基金表現保持一致。"}]', NULL, NULL, 5, 972, NULL),
(973, 'carrier liability', '/''kærɪər ˌlaɪəˈbɪlɪti/', 'noun', '{"zh-TW":["承運人責任"],"en":["the legal responsibility of a carrier for loss or damage to goods during transportation"]}', NULL, 'limit carrier liability / carrier liability insurance / determine carrier liability', '[{"en":"The contract specified the extent of carrier liability for damaged goods.","zh-TW":"合同規定了對損壞貨物的承運人責任範圍。"},{"en":"Carriers limit their liability through standard terms and conditions.","zh-TW":"承運人通過標準條款和條件限制其責任。"}]', NULL, NULL, 5, 973, NULL),
(974, 'carry', '/ˈkæri/', 'verb', '{"zh-TW":["攜帶；執行","承擔"],"en":["to transport or convey","to support the weight of"]}', '{"root":{"text":"carry","meaning":"transport (運送)"},"logic":"運送，即「攜帶」。"}', 'carry out / carry on / carry risk', '[{"en":"The team will carry out the plan next quarter.","zh-TW":"團隊將在下季度執行計畫。"},{"en":"All investments carry some degree of risk.","zh-TW":"所有投資都帶有一定程度的風險。"}]', '{"noun":"carrier"}', NULL, 2, 974, NULL),
(975, 'carry-forward', '/ˈkæri ˈfɔːrwərd/', 'noun', '{"zh-TW":["結轉"],"en":["the transfer of an unused amount to a future accounting period"]}', NULL, 'loss carry-forward / tax loss carry-forward', '[{"en":"The company used a tax loss carry-forward to offset future taxable income.","zh-TW":"公司使用稅損結轉來抵消未來的應稅收入。"},{"en":"A carry-forward of unused annual leave must be taken within 12 months.","zh-TW":"未使用年假的結轉必須在12個月內使用。"}]', '{"verb":"carry forward"}', NULL, 5, 975, NULL),
(976, 'carry-on', '/ˈkæri ɒn/', 'noun', '{"zh-TW":["手提行李"],"en":["a bag small enough to be taken on a plane"]}', NULL, 'carry-on bag / carry-on limit', '[{"en":"Each passenger is allowed one carry-on bag.","zh-TW":"每位乘客可攜帶一件手提行李。"},{"en":"Your carry-on must fit in the overhead bin.","zh-TW":"您的手提行李必須放得進頭頂置物箱。"}]', NULL, NULL, 3, 976, NULL),
(977, 'carry-on luggage', '/''kæri ɒn ˌlʌɡɪdʒ/', 'noun', '{"zh-TW":["隨身行李；手提行李"],"en":["luggage small enough to be stored in the overhead compartment of an aircraft"]}', NULL, 'pack carry-on luggage / carry-on luggage allowance / travel with only carry-on luggage', '[{"en":"Traveling with only carry-on luggage eliminates the risk of lost checked bags.","zh-TW":"只帶隨身行李旅行消除了托運行李遺失的風險。"},{"en":"Most airlines allow one piece of carry-on luggage per passenger.","zh-TW":"大多數航空公司允許每位乘客攜帶一件隨身行李。"}]', NULL, NULL, 5, 977, NULL),
(978, 'carrying capacity', '/ˈkæriɪŋ kəˈpæsɪti/', 'noun', '{"zh-TW":["環境承載力"],"en":["the maximum population size that an environment can sustainably support"]}', NULL, 'exceed carrying capacity / ecological carrying capacity / estimate carrying capacity', '[{"en":"Human consumption patterns have exceeded the planet''s carrying capacity.","zh-TW":"人類消費模式已超過地球的環境承載力。"},{"en":"Urban planners must consider the carrying capacity of local water resources.","zh-TW":"城市規劃者必須考慮當地水資源的環境承載力。"}]', NULL, NULL, 5, 978, NULL),
(979, 'cart', '/kɑːrt/', 'noun', '{"zh-TW":["購物車；手推車"],"en":["a vehicle with wheels used for carrying goods"]}', '{"root":{"text":"cart","meaning":"vehicle (車)"},"logic":"源自古英語 cræt（車），指用於搬運的推車。"}', 'shopping cart / add to cart', '[{"en":"Please put the items in the cart.","zh-TW":"請把商品放進購物車。"},{"en":"She added three items to her online cart.","zh-TW":"她在網路購物車中加了三樣商品。"}]', '{"verb":"cart"}', NULL, 1, 979, NULL),
(980, 'cartel', '/kɑːrˈtel/', 'noun', '{"zh-TW":["卡特爾；聯合壟斷"],"en":["a group of companies cooperating illegally to fix prices or output"]}', NULL, 'form a cartel / price-fixing cartel / cartel investigation', '[{"en":"The antitrust authority broke up the cartel for price fixing.","zh-TW":"反壟斷機構因操縱價格而解散了卡特爾。"},{"en":"OPEC is often described as an oil production cartel.","zh-TW":"OPEC常被描述為石油生產卡特爾。"}]', NULL, NULL, 2, 980, NULL),
(981, 'carve', '/kɑːrv/', 'verb', '{"zh-TW":["雕刻"],"en":["to cut a hard material to produce a shape"]}', '{"root":{"text":"carve","meaning":"cut (切割)"},"logic":"源自古英語 ceorfan（切割）。"}', 'carve a statue / carve wood / carve out', '[{"en":"He carved a beautiful figure from wood.","zh-TW":"他用木頭雕刻了一個美麗的人像。"},{"en":"The sculptor carved the marble with great skill.","zh-TW":"雕塑家以高超技藝雕刻大理石。"}]', '{"noun":"carving","noun2":"carver"}', NULL, 2, 981, NULL),
(982, 'carve-out', '/ˈkɑːrvaʊt/', 'noun', '{"zh-TW":["剝離；分拆"],"en":["separating a business unit into a separate entity or sale"]}', NULL, 'complete a carve-out / carve-out strategy', '[{"en":"The carve-out of the logistics division raised 200 million.","zh-TW":"物流部門的剝離籌集了2億元。"},{"en":"A carve-out allows focus on the core business while monetizing assets.","zh-TW":"剝離允許專注於核心業務同時實現資產變現。"}]', NULL, NULL, 3, 982, NULL),
(983, 'cascading failure', '/kæˈskeɪdɪŋ ˈfeɪljər/', 'noun', '{"zh-TW":["連鎖故障"],"en":["a failure in one part of a system that triggers failures in other interconnected parts"]}', NULL, 'prevent cascading failure / manage cascading failure / risk of cascading failure', '[{"en":"The power grid experienced a cascading failure that blacked out three states.","zh-TW":"電力網絡發生了連鎖故障，造成三個州停電。"},{"en":"Cascading failures in financial systems amplify market crises.","zh-TW":"金融系統中的連鎖故障放大了市場危機。"}]', NULL, NULL, 5, 983, NULL),
(984, 'case study', '/keɪs ˈstʌdi/', 'noun', '{"zh-TW":["案例研究"],"en":["a detailed analysis of a specific subject used for learning or illustration"]}', NULL, 'conduct a case study / present a case study', '[{"en":"The professor used a case study to illustrate supply chain risks.","zh-TW":"教授使用案例研究來說明供應鏈風險。"},{"en":"The marketing team prepared a case study on the product launch success.","zh-TW":"行銷團隊準備了一個關於產品發佈成功的案例研究。"}]', NULL, NULL, 4, 984, NULL),
(985, 'cash and carry', '/kæʃ ænd ˈkæri/', 'noun', '{"zh-TW":["現購自運；現金交易"],"en":["a wholesale model where buyers pay cash and transport goods themselves"]}', NULL, 'use a cash and carry model / cash and carry wholesaler', '[{"en":"Small retailers buy stock from cash and carry wholesalers.","zh-TW":"小型零售商從現購自運批發商那裡購買庫存。"},{"en":"The cash and carry model reduces credit risk for the supplier.","zh-TW":"現購自運模式降低了供應商的信用風險。"}]', NULL, NULL, 5, 985, NULL),
(986, 'cash burn rate', '/kæʃ bɜːrn reɪt/', 'noun', '{"zh-TW":["現金消耗率"],"en":["the rate at which a company spends its cash reserves over time"]}', NULL, 'monitor cash burn rate / reduce cash burn rate', '[{"en":"The startup''s cash burn rate was $500000 per month.","zh-TW":"初創企業的現金消耗率為每月50萬元。"},{"en":"Investors monitor cash burn rate to assess how long a company can operate.","zh-TW":"投資者監控現金消耗率以評估公司能夠運營多長時間。"}]', NULL, NULL, 5, 986, NULL),
(987, 'cash conversion', '/kæʃ kənˈvɜːrʃən/', 'noun', '{"zh-TW":["現金轉換；現金回收"],"en":["the process of converting sales into cash receipts"]}', NULL, 'cash conversion cycle / cash conversion ratio / improve cash conversion', '[{"en":"Faster cash conversion improves liquidity and reduces borrowing needs.","zh-TW":"更快的現金轉換提高了流動性並減少了借貸需求。"},{"en":"The company improved its cash conversion by negotiating shorter payment terms.","zh-TW":"公司通過談判縮短付款條款來提高現金回收效率。"}]', NULL, NULL, 5, 987, NULL),
(988, 'cash conversion cycle', '/kæʃ kənˈvɜːrʒən ˈsaɪkəl/', 'noun', '{"zh-TW":["現金轉換週期"],"en":["the time taken to convert inventory into cash from sales"]}', NULL, 'shorten the cash conversion cycle / manage the cash conversion cycle', '[{"en":"A shorter cash conversion cycle improves liquidity.","zh-TW":"較短的現金轉換週期改善了流動性。"},{"en":"The company optimized its cash conversion cycle through better receivables management.","zh-TW":"公司通過更好的應收帳款管理優化了現金轉換週期。"}]', NULL, NULL, 5, 988, NULL),
(989, 'cash disbursement', '/kæʃ dɪsˈbɜːrsmənt/', 'noun', '{"zh-TW":["現金支出；現金撥付"],"en":["the payment of cash from a fund or account for business expenses"]}', NULL, 'record cash disbursement / cash disbursement journal', '[{"en":"All cash disbursements must be approved by the finance manager.","zh-TW":"所有現金支出必須由財務經理批准。"},{"en":"The cash disbursement journal tracks all outgoing payments chronologically.","zh-TW":"現金支出日記帳按時間順序追蹤所有外出付款。"}]', '{"synonym":"cash payment"}', NULL, 5, 989, NULL),
(990, 'cash dividend', '/kæʃ ˈdɪvɪdend/', 'noun', '{"zh-TW":["現金股息"],"en":["a payment made to shareholders from company profits in the form of cash"]}', NULL, 'declare a cash dividend / cash dividend per share', '[{"en":"The board declared a cash dividend of $0.50 per share.","zh-TW":"董事會宣布每股現金股息為0.50元。"},{"en":"Cash dividends are taxed as income in most jurisdictions.","zh-TW":"現金股息在大多數司法管轄區被視為收入徵稅。"}]', '{"opposite":"stock dividend"}', NULL, 5, 990, NULL),
(991, 'cash equivalents', '/kæʃ ɪˈkwɪvələnts/', 'noun', '{"zh-TW":["現金等價物"],"en":["highly liquid assets that can be converted to cash quickly and with minimal risk"]}', NULL, 'hold cash equivalents / cash and cash equivalents', '[{"en":"Money market funds are classified as cash equivalents on the balance sheet.","zh-TW":"貨幣市場基金在資產負債表上被歸類為現金等價物。"},{"en":"Cash equivalents improve a company''s liquidity position.","zh-TW":"現金等價物改善了公司的流動性狀況。"}]', NULL, NULL, 5, 991, NULL),
(992, 'cash flow', '/kæʃ floʊ/', 'noun', '{"zh-TW":["現金流"],"en":["the movement of money in and out of a business"]}', NULL, 'positive cash flow / cash flow statement / cash flow management', '[{"en":"Strong cash flow allows the company to invest in growth.","zh-TW":"強勁的現金流使公司能夠投資於增長。"},{"en":"The startup struggled with negative cash flow in its first year.","zh-TW":"新創公司在第一年面臨負現金流的困境。"}]', '{"adjective":"cash-flow positive"}', NULL, 3, 992, NULL),
(993, 'cash flow statement', '/kæʃ floʊ ˈsteɪtmənt/', 'noun', '{"zh-TW":["現金流量表"],"en":["a financial statement showing cash inflows and outflows over a period"]}', NULL, 'prepare a cash flow statement / review the cash flow statement', '[{"en":"The cash flow statement showed strong operating cash generation.","zh-TW":"現金流量表顯示了強勁的營業現金產生。"},{"en":"Investors use the cash flow statement to assess liquidity.","zh-TW":"投資者使用現金流量表評估流動性。"}]', NULL, NULL, 5, 993, NULL),
(994, 'cash management', '/kæʃ ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["現金管理"],"en":["the monitoring and control of a company cash flows"]}', NULL, 'improve cash management / cash management system', '[{"en":"Effective cash management ensures bills are paid on time.","zh-TW":"有效的現金管理確保按時支付賬單。"},{"en":"The treasury function oversees all cash management activities.","zh-TW":"財資職能監督所有現金管理活動。"}]', NULL, NULL, 5, 994, NULL),
(995, 'cash register', '/kæʃ ˈrɛdʒɪstər/', 'noun', '{"zh-TW":["收銀機"],"en":["a machine for calculating and recording sales transactions"]}', NULL, 'use a cash register / cash register receipt', '[{"en":"The cashier processed the transaction using the cash register.","zh-TW":"收銀員使用收銀機處理了交易。"},{"en":"Modern cash registers can also process card payments.","zh-TW":"現代收銀機也可以處理刷卡付款。"}]', NULL, NULL, 5, 995, NULL),
(996, 'cash reserve', '/kæʃ rɪˈzɜːrv/', 'noun', '{"zh-TW":["現金儲備"],"en":["funds held by a company to meet unexpected expenses or opportunities"]}', NULL, 'maintain a cash reserve / draw on cash reserves', '[{"en":"A three-month cash reserve provides a safety net for the business.","zh-TW":"三個月的現金儲備為企業提供了安全保障。"},{"en":"The company dipped into its cash reserves during the sales slump.","zh-TW":"銷售低迷期間，公司動用了現金儲備。"}]', NULL, NULL, 4, 996, NULL),
(997, 'cashback', '/ˈkæʃbæk/', 'noun', '{"zh-TW":["現金回饋"],"en":["a reward scheme where a portion of spending is returned to the buyer"]}', NULL, 'cashback offer / earn cashback / cashback card / cashback program', '[{"en":"The credit card offers 2% cashback on all purchases.","zh-TW":"信用卡對所有購買提供2%的現金回饋。"},{"en":"Cashback incentives increased average transaction size.","zh-TW":"現金回饋激勵增加了平均交易金額。"}]', NULL, NULL, 3, 997, NULL),
(998, 'cashier', '/kæˈʃɪr/', 'noun', '{"zh-TW":["收銀員"],"en":["a person who handles payments in a store"]}', '{"root":{"text":"cash","meaning":"money (現金)"},"suffix":{"text":"-ier","meaning":"person who (從事…的人)"},"logic":"處理現金的人，即「收銀員」。"}', 'cashier counter / head cashier', '[{"en":"The cashier scanned all the items.","zh-TW":"收銀員掃描了所有商品。"},{"en":"Please pay the cashier at the front.","zh-TW":"請到前面的收銀台付款。"}]', '{"noun":"cash"}', NULL, 3, 998, NULL),
(999, 'caste system', '/kɑːst ˈsɪstəm/', 'noun', '{"zh-TW":["種姓制度"],"en":["a social hierarchy in which people are born into a fixed rank"]}', NULL, 'caste discrimination / caste system inequality / challenge the caste system', '[{"en":"The caste system creates structural barriers to social mobility.","zh-TW":"種姓制度在社會流動性方面創造了結構性障礙。"},{"en":"Activists work to dismantle caste-based discrimination in law and practice.","zh-TW":"活動人士致力於在法律和實踐中消除基於種姓的歧視。"}]', '{"adjective":"caste-based"}', NULL, 4, 999, NULL);